function ArticleSearch({ projectId, savedExternalIds, initialQuery, onQueryContextChange }: { projectId: number; savedExternalIds: Set<string>; initialQuery: string; onQueryContextChange: (query: string) => void }) {
  const utils = trpc.useUtils();
  const [query, setQuery] = useState(initialQuery); const [submittedQuery, setSubmittedQuery] = useState("");
  const search = trpc.cartographer.search.useQuery({ query: submittedQuery || "pesquisa", limit: 10 }, { enabled: submittedQuery.length >= 3, retry: false });
  const save = trpc.cartographer.saveArticle.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); toast.success("Artigo adicionado à biblioteca do projeto."); }, onError: error => toast.error(error.message) });
  useEffect(() => { if (initialQuery && !query) setQuery(initialQuery); }, [initialQuery, query]);
  useEffect(() => { onQueryContextChange(submittedQuery || query); }, [onQueryContextChange, query, submittedQuery]);
  const submit = (event: FormEvent) => { event.preventDefault(); const normalized = query.trim(); if (normalized.length < 3) { toast.error("Use ao menos 3 caracteres na busca."); return; } setSubmittedQuery(normalized); };
  return <section className="space-y-5"><form onSubmit={submit} className="flex border border-slate-300 bg-white p-1 shadow-sm"><Input value={query} onChange={event => setQuery(event.target.value)} placeholder="Ex.: intervenções digitais para ansiedade em universitários" className="h-12 border-0 bg-transparent text-base shadow-none focus-visible:ring-0" /><Button type="submit" className="h-12 bg-[#0A192F] px-5 hover:bg-[#152c4b]" disabled={search.isFetching}>{search.isFetching ? <Loader2 className="h-4 w-4 animate-spin" /> : <><Search className="mr-2 h-4 w-4" />Buscar</>}</Button></form>
    {submittedQuery && <><div className="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-500"><span>{search.isFetching ? "Consultando bases acadêmicas…" : `${search.data?.results.length ?? 0} resultados para “${submittedQuery}”`}</span>{search.data?.provider && <Badge variant="outline" className="rounded-none border-amber-300 bg-amber-50 text-amber-900">{search.data.provider}</Badge>}</div>{search.data?.sources?.length ? <div className="flex flex-wrap gap-2 border-l-2 border-amber-300 bg-slate-50 px-3 py-3 text-[11px] leading-4 text-slate-600" aria-label="Cobertura das fontes consultadas">{search.data.sources.map(source => <span key={source.id} className={cn("border px-2 py-1", source.status === "available" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : source.status === "requires_key" ? "border-amber-300 bg-amber-50 text-amber-900" : "border-slate-200 bg-white text-slate-500")}><strong>{source.label}</strong>{source.status === "available" ? ` · ${source.resultCount}` : source.status === "requires_key" ? " · chave pendente" : " · indisponível nesta consulta"}</span>)}</div> : null}</>}
    {search.error && <div className="border border-red-200 bg-red-50 p-4 text-sm text-red-800"><CircleAlert className="mr-2 inline h-4 w-4" />{search.error.message}</div>}
    <div className="space-y-3">{search.data?.results.map(article => <SearchResult key={`${article.source}-${article.externalId}`} article={article} saved={savedExternalIds.has(article.externalId)} pending={save.isPending} onSave={() => save.mutate({ projectId, article })} />)}</div>
    {submittedQuery && !search.isFetching && (search.data?.results.length ?? 0) === 0 && <div className="border border-dashed border-slate-300 bg-white p-12 text-center text-slate-500">Não encontramos trabalhos com essa combinação. Tente termos mais amplos ou em inglês.</div>}
  </section>;
}

function DiscoveryWorkspace({ projectId, savedExternalIds, savedCount, context }: { projectId: number; savedExternalIds: Set<string>; savedCount: number; context: ReticulaSearchContext }) {
  const [discoveryQuery, setDiscoveryQuery] = useState(context.query);
  const reticulaUrl = createReticulaUrl(discoveryQuery, context);
  return <section className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_300px]">
    <div className="min-w-0 border border-slate-200 bg-white p-5 md:p-7"><div className="mb-6 flex flex-col justify-between gap-4 border-b border-slate-200 pb-5 md:flex-row md:items-end"><div><p className="text-[10px] font-bold tracking-[.18em] text-amber-700">MESA DE DESCOBERTA</p><h2 className="mt-2 font-reading text-2xl font-black text-[#0A192F]">Mapeie antes de decidir.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-slate-600">Combine uma pergunta precisa com fontes abertas, compare relevância e registre apenas estudos que merecem entrar no corpus.</p></div><span className="inline-flex w-fit items-center gap-2 border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-900"><Search className="h-3.5 w-3.5" />Busca semântica</span></div>{context.fromReticula && <div className="mb-5 border-l-2 border-amber-400 bg-amber-50 px-4 py-3 text-xs leading-5 text-amber-950"><strong>Consulta recebida do Retícula.</strong> As coordenadas foram pré-preenchidas; revise os termos e acione a busca quando desejar.</div>}<ArticleSearch projectId={projectId} savedExternalIds={savedExternalIds} initialQuery={context.query} onQueryContextChange={setDiscoveryQuery} /></div>
    <aside className="h-fit border border-slate-200 bg-[#0A192F] p-6 text-white xl:sticky xl:top-24"><p className="text-[10px] font-bold tracking-[.18em] text-amber-300">MAPA DA REVISÃO</p><h3 className="mt-3 font-reading text-xl font-black leading-snug">A descoberta ganha sentido dentro do corpus.</h3><p className="mt-3 text-sm leading-6 text-slate-300">A relevância orienta a triagem; a decisão de salvar continua sendo do pesquisador.</p><a href={reticulaUrl} target="_blank" rel="noreferrer" className="mt-5 block"><Button variant="outline" className="w-full rounded-none border-amber-300 bg-transparent text-amber-200 hover:bg-amber-300 hover:text-slate-950"><ExternalLink className="mr-2 h-4 w-4" />Abrir Retícula</Button></a><p className="mt-2 text-[11px] leading-4 text-slate-400">Abre uma nova aba com o contexto disponível; o Retícula só consulta fontes após sua confirmação.</p><div className="mt-5"><RisImportDialog projectId={projectId} /></div><div className="mt-6 space-y-3 border-y border-white/15 py-5"><div className="flex items-end justify-between"><span className="text-xs uppercase tracking-[.14em] text-slate-400">Corpus salvo</span><strong className="font-reading text-3xl text-amber-300">{savedCount}</strong></div><div className="border-l-2 border-amber-300 pl-3 text-xs leading-5 text-slate-300">A consulta combina Semantic Scholar, OpenAlex, Europe PMC/PubMed, Crossref, SciELO, OpenAIRE e arXiv. O CORE permanece indisponível enquanto a chave não for cadastrada.</div></div><div className="mt-6 space-y-3"><p className="text-[10px] font-bold tracking-[.16em] text-amber-300">RITUAL DE SELEÇÃO</p><ol className="space-y-3 text-sm leading-5 text-slate-200"><li><span className="mr-2 text-amber-300">01</span>Formule termos e relações.</li><li><span className="mr-2 text-amber-300">02</span>Compare resumo, autoria e relevância.</li><li><span className="mr-2 text-amber-300">03</span>Salve somente o que será rastreado.</li></ol></div></aside>
  </section>;
}

function SearchResult({ article, saved, pending, onSave }: { article: ArticleResult; saved: boolean; pending: boolean; onSave: () => void }) {
  return <article className="border border-slate-200 bg-white p-5 transition-shadow hover:shadow-md"><div className="flex gap-4"><div className="hidden h-12 w-12 shrink-0 items-center justify-center border border-amber-300 bg-amber-50 text-sm font-bold text-amber-800 sm:flex">{article.relevanceScore}%</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2 text-xs text-slate-500"><Badge variant="secondary" className="rounded-none bg-slate-100 text-slate-600">{article.year ?? "s/d"}</Badge><span>{article.citationCount.toLocaleString("pt-BR")} citações</span><span className="text-amber-700">relevância {article.relevanceScore}%</span></div><h3 className="mt-2 font-reading text-lg font-bold leading-snug text-[#0A192F]">{article.title}</h3><p className="mt-1 text-sm text-slate-600">{article.authors.slice(0, 4).join(", ") || "Autoria não informada"}{article.authors.length > 4 ? " et al." : ""}</p>{article.abstract ? <p className="mt-3 line-clamp-3 text-sm leading-6 text-slate-600">{article.abstract}</p> : <p className="mt-3 text-sm italic text-slate-400">Resumo não disponibilizado pela base consultada.</p>}<div className="mt-4 flex flex-wrap items-center gap-3 text-xs">{article.doi && <a href={`https://doi.org/${article.doi}`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-semibold text-slate-600 hover:text-amber-800"><ExternalLink className="h-3 w-3" />DOI: {article.doi}</a>}<span className="uppercase tracking-wider text-slate-400">{articleSourceLabels[article.source]}</span></div></div><Button onClick={onSave} disabled={saved || pending} variant={saved ? "secondary" : "outline"} className={cn("h-9 shrink-0 rounded-none", !saved && "border-[#0A192F] text-[#0A192F] hover:bg-[#0A192F] hover:text-white")}>{saved ? <><Check className="mr-1 h-4 w-4" />Salvo</> : <><Plus className="mr-1 h-4 w-4" />Salvar</>}</Button></div></article>;
}

function ExtractionDialog({ article, projectId }: { article: any; projectId: number }) {
  const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [failure, setFailure] = useState<string | null>(null);
  const extract = trpc.cartographer.extractArticle.useMutation({ onSuccess: () => { setFailure(null); utils.cartographer.projectOverview.invalidate({ projectId }); toast.success("Extração concluída e vinculada aos trechos de origem."); }, onError: error => { setFailure(error.message); toast.error(error.message); } });
  const extraction = article.extraction;
  const labels: Array<[string, string]> = [["objective", "Objetivo"], ["methodology", "Metodologia"], ["sample", "Amostra"], ["mainFindings", "Principais resultados"], ["limitations", "Limitações"]];
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button size="sm" variant="outline" className="rounded-none border-amber-300 text-amber-900 hover:bg-amber-50"><Sparkles className="mr-1.5 h-3.5" />{extraction ? "Ver extração" : "Extrair com IA"}</Button></DialogTrigger><DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto"><DialogHeader><DialogTitle className="font-reading text-xl leading-snug text-[#0A192F]">{article.title}</DialogTitle><DialogDescription>Os campos são derivados exclusivamente do resumo público e preservam a evidência de origem.</DialogDescription></DialogHeader>{!extraction ? <div className="py-6"><p className="mb-5 text-sm leading-6 text-slate-600">A extração estruturará objetivo, metodologia, amostra, resultados e limitações. Os trechos de prova serão validados contra o resumo original antes de serem exibidos.</p>{failure && <div role="alert" className="mb-4 border border-red-200 bg-red-50 p-3 text-sm leading-6 text-red-800"><CircleAlert className="mr-2 inline h-4 w-4" />{failure} <span className="font-semibold">Revise o resumo ou tente novamente.</span></div>}<Button onClick={() => { setFailure(null); extract.mutate({ projectId, articleId: article.id }); }} disabled={extract.isPending} className="bg-[#0A192F] hover:bg-[#152c4b]">{extract.isPending ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Extraindo evidências…</> : <><Sparkles className="mr-2 h-4 w-4" />Gerar extração rastreável</>}</Button></div> : <div className="space-y-4 py-2">{labels.map(([key, label]) => { const evidence = extraction.evidence.find((item: any) => item.field === key); return <div key={key} className="border-l-2 border-amber-400 pl-4"><p className="text-xs font-bold uppercase tracking-wider text-amber-800">{label}</p><p className="mt-1 text-sm leading-6 text-[#0A192F]">{extraction[key]}</p>{evidence && <blockquote className="mt-2 border-l border-slate-300 pl-3 text-xs italic leading-5 text-slate-500">“{evidence.sourceText}”</blockquote>}</div>; })}</div>}</DialogContent></Dialog>;
}

function ScreeningDialog({ article, projectId, screening }: { article: any; projectId: number; screening?: any }) {
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [stage, setStage] = useState<"title_abstract" | "full_text">(screening?.stage ?? "title_abstract");
  const [decision, setDecision] = useState<"pending" | "included" | "excluded">(screening?.decision ?? "pending");
  const [reason, setReason] = useState(screening?.reason ?? "");
  useEffect(() => { if (open) { setStage(screening?.stage ?? "title_abstract"); setDecision(screening?.decision ?? "pending"); setReason(screening?.reason ?? ""); } }, [open, screening?.stage, screening?.decision, screening?.reason]);
  const save = trpc.cartographer.screenArticle.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); setOpen(false); toast.success("Decisão de triagem registrada."); }, onError: error => toast.error(error.message) });
  const label = screening?.decision === "included" ? "Incluído" : screening?.decision === "excluded" ? "Excluído" : "Triar";
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button size="sm" variant="outline" className="rounded-none border-slate-300 text-slate-700 hover:bg-slate-50"><FileCheck2 className="mr-1.5 h-3.5 w-3.5" />{label}</Button></DialogTrigger><DialogContent className="max-w-lg"><DialogHeader><DialogTitle className="font-reading text-xl text-[#0A192F]">Triagem transparente</DialogTitle><DialogDescription>Registre a decisão para este estudo e preserve a justificativa no projeto.</DialogDescription></DialogHeader><div className="space-y-5 pt-2"><p className="font-reading text-sm font-bold leading-6 text-[#0A192F]">{article.title}</p><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Etapa</Label><Select value={stage} onValueChange={value => setStage(value as typeof stage)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="title_abstract">Título e resumo</SelectItem><SelectItem value="full_text">Texto completo</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Decisão</Label><Select value={decision} onValueChange={value => setDecision(value as typeof decision)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="pending">Pendente</SelectItem><SelectItem value="included">Incluir</SelectItem><SelectItem value="excluded">Excluir</SelectItem></SelectContent></Select></div></div><div className="space-y-2"><Label htmlFor={`screening-reason-${article.id}`}>Justificativa <span className="text-muted-foreground">(especialmente para exclusão)</span></Label><Textarea id={`screening-reason-${article.id}`} value={reason} onChange={event => setReason(event.target.value)} placeholder="Ex.: população fora do escopo, método incompatível, duplicata confirmada." className="min-h-24" /></div><Button type="button" disabled={save.isPending} onClick={() => save.mutate({ projectId, articleId: article.id, stage, decision, reason: reason.trim() || undefined })} className="w-full rounded-none bg-[#0A192F] hover:bg-[#152c4b]">{save.isPending ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Salvando decisão…</> : <><FileCheck2 className="mr-2 h-4 w-4" />Registrar decisão</>}</Button></div></DialogContent></Dialog>;
}

function ScreeningSummary({ articles, screenings, possibleDuplicateGroups, possibleOverlapPairs }: { articles: any[]; screenings: any[]; possibleDuplicateGroups: number[][]; possibleOverlapPairs: Array<[number, number]> }) {
  const included = screenings.filter(screening => screening.decision === "included").length;
  const excluded = screenings.filter(screening => screening.decision === "excluded").length;
  const pending = articles.length - included - excluded;
  const fullText = screenings.filter(screening => screening.stage === "full_text").length;
  return <div className="mb-5 border border-slate-200 bg-slate-50 p-4"><div className="flex flex-col justify-between gap-3 md:flex-row md:items-center"><div><p className="text-[10px] font-bold tracking-[.16em] text-amber-700">REGISTRO DE TRIAGEM</p><p className="mt-1 text-sm text-slate-600">Contagens derivadas somente das decisões documentadas neste corpus.</p></div><div className="grid grid-cols-4 divide-x divide-slate-200 border border-slate-200 bg-white text-center"><div className="px-3 py-2"><strong className="block font-reading text-lg text-[#0A192F]">{articles.length}</strong><span className="text-[10px] text-slate-500">identificados</span></div><div className="px-3 py-2"><strong className="block font-reading text-lg text-amber-800">{pending}</strong><span className="text-[10px] text-slate-500">pendentes</span></div><div className="px-3 py-2"><strong className="block font-reading text-lg text-emerald-700">{included}</strong><span className="text-[10px] text-slate-500">incluídos</span></div><div className="px-3 py-2"><strong className="block font-reading text-lg text-slate-700">{excluded}</strong><span className="text-[10px] text-slate-500">excluídos</span></div></div></div><p className="mt-3 text-xs text-slate-500">{fullText} decisão(ões) estão na etapa de texto completo. Este registro está pronto para alimentar um fluxo PRISMA, sem inventar contagens externas ao corpus.</p>{(possibleDuplicateGroups.length > 0 || possibleOverlapPairs.length > 0) && <div className="mt-3 border-l-2 border-amber-400 bg-amber-50 px-3 py-2 text-xs leading-5 text-amber-950"><CircleAlert className="mr-1 inline h-3.5 w-3.5" /><strong>Revisão manual recomendada.</strong> {possibleDuplicateGroups.length > 0 && `${possibleDuplicateGroups.length} grupo(s) de possível duplicata por DOI ou título normalizado. `}{possibleOverlapPairs.length > 0 && `${possibleOverlapPairs.length} par(es) de possível sobreposição bibliográfica por autoria, ano e título; isso não confirma compartilhamento de amostra.`}</div>}</div>;
}

function LibraryContext({ articles }: { articles: any[] }) {
  const read = articles.filter(article => article.isRead).length;
  const extracted = articles.filter(article => article.extraction).length;
  const pending = articles.length - extracted;
  return <aside className="h-fit border border-slate-200 bg-[#0A192F] p-6 text-white xl:sticky xl:top-24"><p className="text-[10px] font-bold tracking-[.18em] text-amber-300">PAINEL DE PROVENIÊNCIA</p><h3 className="mt-3 font-reading text-xl font-black leading-snug">A leitura é uma decisão de método.</h3><p className="mt-3 text-sm leading-6 text-slate-300">Acompanhe o que já foi lido, extraído e ainda precisa de evidência estruturada.</p><dl className="mt-7 divide-y divide-white/15 border-y border-white/15"><div className="flex items-center justify-between py-3"><dt className="text-xs text-slate-300">Estudos selecionados</dt><dd className="font-reading text-xl font-black text-amber-300">{articles.length}</dd></div><div className="flex items-center justify-between py-3"><dt className="text-xs text-slate-300">Leituras concluídas</dt><dd className="font-reading text-xl font-black text-white">{read}</dd></div><div className="flex items-center justify-between py-3"><dt className="text-xs text-slate-300">Aguardando extração</dt><dd className="font-reading text-xl font-black text-white">{pending}</dd></div></dl><div className="mt-6 border-l-2 border-amber-300 pl-3 text-xs leading-5 text-slate-300">{extracted ? `${extracted} estudo${extracted === 1 ? " possui" : "s possuem"} evidência estruturada e rastreável.` : "Priorize a extração dos estudos mais relevantes antes de redigir a síntese."}</div></aside>;
}

function DuplicateReviewPanel({ projectId }: { projectId: number }) {
  const utils = trpc.useUtils();
  const { data: candidates = [], isLoading } = trpc.cartographer.duplicateReviewCandidates.useQuery({ projectId });
  const [notes, setNotes] = useState<Record<string, string>>({});
  const review = trpc.cartographer.reviewDuplicateCandidate.useMutation({
    onSuccess: () => { utils.cartographer.duplicateReviewCandidates.invalidate({ projectId }); toast.success("Decisão registrada. Nenhum estudo foi removido ou mesclado."); },
    onError: error => toast.error(error.message),
  });
  if (!isLoading && !candidates.length) return null;
  return <section className="border border-amber-200 bg-amber-50 p-5"><div className="flex flex-col justify-between gap-3 border-b border-amber-200 pb-4 md:flex-row"><div><p className="text-[10px] font-bold tracking-[.16em] text-amber-800">REVISÃO ASSISTIDA</p><h3 className="mt-1 font-reading text-xl font-black text-[#0A192F]">Títulos semelhantes pedem uma decisão humana.</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-700">O escore é um indício determinístico de título, autoria, ano e DOI. Ele não confirma identidade, não exclui estudos e não produz mesclas automáticas.</p></div><Badge variant="outline" className="h-fit w-fit rounded-none border-amber-300 bg-white text-amber-900">{isLoading ? "Avaliando…" : `${candidates.length} par(es)`}</Badge></div><div className="mt-4 space-y-4">{candidates.map((candidate: any) => { const pairKey = `${candidate.articleIdA}:${candidate.articleIdB}`; const note = notes[pairKey] ?? candidate.review?.reviewerNote ?? ""; return <article key={pairKey} className="border border-amber-200 bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[11px] font-bold uppercase tracking-[.12em] text-amber-800">Indício de similaridade: {candidate.score}%</p><p className="mt-1 text-xs leading-5 text-slate-600">{candidate.reasons.join(" ")}</p></div>{candidate.review && <Badge className={cn("rounded-none", candidate.review.decision === "same_study" ? "bg-amber-600 text-white hover:bg-amber-600" : "bg-emerald-700 text-white hover:bg-emerald-700")}>{candidate.review.decision === "same_study" ? "Mesmo estudo — revisado" : "Distintos — revisado"}</Badge>}</div><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="border-l-2 border-slate-300 bg-slate-50 p-3"><p className="text-[10px] font-bold tracking-[.12em] text-slate-500">ESTUDO A</p><p className="mt-1 font-reading text-sm font-bold leading-5 text-[#0A192F]">{candidate.articleA?.title}</p><p className="mt-2 text-xs text-slate-500">{candidate.articleA?.authors?.join(", ") || "Autoria não informada"} · {candidate.articleA?.year ?? "s/d"}</p></div><div className="border-l-2 border-slate-300 bg-slate-50 p-3"><p className="text-[10px] font-bold tracking-[.12em] text-slate-500">ESTUDO B</p><p className="mt-1 font-reading text-sm font-bold leading-5 text-[#0A192F]">{candidate.articleB?.title}</p><p className="mt-2 text-xs text-slate-500">{candidate.articleB?.authors?.join(", ") || "Autoria não informada"} · {candidate.articleB?.year ?? "s/d"}</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-[minmax(0,1fr)_auto_auto]"><Textarea aria-label={`Nota de revisão para o par ${candidate.articleIdA} e ${candidate.articleIdB}`} value={note} onChange={event => setNotes(current => ({ ...current, [pairKey]: event.target.value }))} placeholder="Nota opcional: justifique a decisão." className="min-h-20 rounded-none bg-white text-sm" maxLength={2000} /><Button type="button" variant="outline" disabled={review.isPending} onClick={() => review.mutate({ projectId, articleIdA: candidate.articleIdA, articleIdB: candidate.articleIdB, decision: "distinct", reviewerNote: note.trim() || undefined })} className="rounded-none border-emerald-700 text-emerald-800 hover:bg-emerald-50">Manter distintos</Button><Button type="button" disabled={review.isPending} onClick={() => review.mutate({ projectId, articleIdA: candidate.articleIdA, articleIdB: candidate.articleIdB, decision: "same_study", reviewerNote: note.trim() || undefined })} className="rounded-none bg-[#0A192F] hover:bg-[#152c4b]">Mesmo estudo</Button></div>{candidate.review?.reviewedAt && <p className="mt-3 text-[11px] text-slate-500">Última decisão: {new Date(candidate.review.reviewedAt).toLocaleString("pt-BR")}.</p>}</article>; })}</div></section>;
}

function LibraryView({ projectId, projectName, articles, screenings = [], possibleDuplicateGroups = [], possibleOverlapPairs = [], prisma }: { projectId: number; projectName: string; articles: any[]; screenings?: any[]; possibleDuplicateGroups?: number[][]; possibleOverlapPairs?: Array<[number, number]>; prisma?: any }) {
  const utils = trpc.useUtils();
  const toggle = trpc.cartographer.toggleArticleRead.useMutation({ onSuccess: () => utils.cartographer.projectOverview.invalidate({ projectId }), onError: error => toast.error(error.message) });
  const remove = trpc.cartographer.removeArticle.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); toast.success("Artigo removido da biblioteca."); }, onError: error => toast.error(error.message) });
  const screeningByArticleId = new Map(screenings.map(screening => [screening.articleId, screening]));
  if (!articles.length) return <div className="border border-dashed border-slate-300 bg-white p-12 text-center"><Library className="mx-auto h-7 w-7 text-amber-700" /><h3 className="mt-4 font-reading text-xl font-bold text-[#0A192F]">Sua biblioteca está vazia.</h3><p className="mt-2 text-sm text-slate-500">Busque trabalhos e salve somente os que merecem ser rastreados.</p></div>;
  return <section className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_300px]"><div className="space-y-3"><div className="flex flex-wrap items-end justify-between gap-3 border-b border-slate-200 pb-4"><div><p className="text-[10px] font-bold tracking-[.18em] text-amber-700">CORPUS SELECIONADO</p><p className="mt-1 text-sm text-slate-500">{articles.length} estudo{articles.length === 1 ? "" : "s"} guardado{articles.length === 1 ? "" : "s"} nesta revisão.</p></div><span className="border border-amber-200 bg-amber-50 px-3 py-1 text-xs font-bold text-amber-900">Leitura + extração + triagem</span></div><ScreeningSummary articles={articles} screenings={screenings} possibleDuplicateGroups={possibleDuplicateGroups} possibleOverlapPairs={possibleOverlapPairs} /><DuplicateReviewPanel projectId={projectId} />{prisma && <PrismaDiagram projectName={projectName} counts={prisma} />}{articles.map(article => { const screening = screeningByArticleId.get(article.id); return <article key={article.id} className="border border-slate-200 bg-white p-5 transition-shadow hover:shadow-[0_12px_30px_rgba(10,25,47,.08)]"><div className="grid grid-cols-[20px_minmax(0,1fr)] items-start gap-4 sm:grid-cols-[20px_minmax(0,1fr)_auto]"><button onClick={() => toggle.mutate({ projectId, articleId: article.id, isRead: !article.isRead })} className={cn("mt-1 flex h-5 w-5 shrink-0 items-center justify-center border", article.isRead ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-300 bg-white")} aria-label={article.isRead ? "Marcar como não lido" : "Marcar como lido"}>{article.isRead && <Check className="h-3.5 w-3.5" />}</button><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge variant="secondary" className="rounded-none text-[10px]">{article.publicationYear ?? "s/d"}</Badge>{article.extraction ? <Badge className="rounded-none bg-amber-100 text-[10px] text-amber-900 hover:bg-amber-100">EXTRAÍDO</Badge> : <Badge variant="outline" className="rounded-none text-[10px] text-slate-500">PENDENTE</Badge>}{article.document?.extractionStatus === "ready" && <Badge className="rounded-none bg-sky-100 text-[10px] text-sky-900 hover:bg-sky-100">PDF · TEXTO INTEGRAL</Badge>}{screening?.decision === "included" && <Badge className="rounded-none bg-emerald-100 text-[10px] text-emerald-800 hover:bg-emerald-100">INCLUÍDO</Badge>}{screening?.decision === "excluded" && <Badge className="rounded-none bg-red-100 text-[10px] text-red-800 hover:bg-red-100">EXCLUÍDO</Badge>}{article.isRead && <span className="text-xs text-emerald-700">Lido</span>}</div><h3 className={cn("mt-2 font-reading text-lg font-bold leading-snug text-[#0A192F]", article.isRead && "text-slate-500 line-through decoration-slate-300")}>{article.title}</h3><p className="mt-1 text-sm text-slate-600">{article.authors.slice(0, 4).join(", ") || "Autoria não informada"}</p>{article.abstract && <p className="mt-2 line-clamp-2 text-sm leading-6 text-slate-500">{article.abstract}</p>}{screening?.reason && <p className="mt-3 border-l-2 border-slate-200 pl-3 text-xs leading-5 text-slate-500"><strong>Justificativa:</strong> {screening.reason}</p>}</div><div className="col-span-2 flex items-center justify-end gap-2 border-t border-slate-100 pt-3 sm:col-span-1 sm:col-start-3 sm:row-start-1 sm:border-t-0 sm:pt-0 sm:flex-col"><PdfImportDialog article={article} projectId={projectId} /><ScreeningDialog article={article} projectId={projectId} screening={screening} /><ExtractionDialog article={article} projectId={projectId} /><Button size="icon" variant="ghost" className="h-8 w-8 text-slate-400 hover:bg-red-50 hover:text-red-600" onClick={() => remove.mutate({ projectId, articleId: article.id })} aria-label="Remover artigo"><Trash2 className="h-4 w-4" /></Button></div></div></article>; })}</div><LibraryContext articles={articles} /></section>;
}

function NarrativeThemes({ projectId, articles, themes = [] }: { projectId: number; articles: any[]; themes?: any[] }) {
  const utils = trpc.useUtils();
  const [editingId, setEditingId] = useState<number | null>(null);
  const [title, setTitle] = useState("");
  const [interpretation, setInterpretation] = useState("");
  const [articleIds, setArticleIds] = useState<number[]>([]);
  const reset = () => { setEditingId(null); setTitle(""); setInterpretation(""); setArticleIds([]); };
  const create = trpc.cartographer.createNarrativeTheme.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); reset(); toast.success("Tema narrativo salvo com suas evidências."); }, onError: error => toast.error(error.message) });
  const update = trpc.cartographer.updateNarrativeTheme.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); reset(); toast.success("Tema narrativo atualizado."); }, onError: error => toast.error(error.message) });
  const remove = trpc.cartographer.removeNarrativeTheme.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); toast.success("Tema narrativo removido."); }, onError: error => toast.error(error.message) });
  const save = () => { if (title.trim().length < 3 || interpretation.trim().length < 10 || articleIds.length === 0) { toast.error("Informe um tema, uma interpretação e ao menos uma evidência do corpus."); return; } const theme = { title: title.trim(), interpretation: interpretation.trim(), articleIds }; if (editingId) update.mutate({ projectId, themeId: editingId, theme }); else create.mutate({ projectId, theme }); };
  const toggleArticle = (articleId: number) => setArticleIds(current => current.includes(articleId) ? current.filter(id => id !== articleId) : [...current, articleId]);
  return <section className="mt-8 border border-slate-200 bg-white p-6 md:p-8"><div className="flex flex-col justify-between gap-3 border-b border-slate-200 pb-5 md:flex-row md:items-end"><div><p className="text-[10px] font-bold tracking-[.18em] text-amber-700">SÍNTESE QUALITATIVA E NARRATIVA</p><h3 className="mt-1 font-reading text-xl font-black text-[#0A192F]">Construa temas, não apenas contagens.</h3><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Registre sua interpretação e vincule explicitamente quais estudos a sustentam. Esta área não faz inferências automáticas sobre o corpus.</p></div><Badge variant="outline" className="w-fit rounded-none border-amber-300 bg-amber-50 text-amber-900">{themes.length} tema(s)</Badge></div><div className="mt-6 grid gap-7 xl:grid-cols-[minmax(0,1fr)_minmax(320px,.8fr)]"><div className="space-y-3">{themes.length === 0 ? <div className="border border-dashed border-slate-300 bg-slate-50 p-6 text-sm leading-6 text-slate-500">Ainda não há temas narrativos. Use o formulário ao lado para relacionar uma interpretação aos estudos do corpus.</div> : themes.map(theme => { const evidenceArticles = articles.filter(article => theme.articleIds.includes(article.id)); return <article key={theme.id} className="border border-slate-200 p-5"><div className="flex items-start justify-between gap-3"><div><p className="font-reading text-lg font-bold text-[#0A192F]">{theme.title}</p><p className="mt-2 text-sm leading-6 text-slate-700">{theme.interpretation}</p></div><div className="flex shrink-0 gap-1"><Button type="button" size="sm" variant="ghost" className="h-8 text-xs text-slate-600" onClick={() => { setEditingId(theme.id); setTitle(theme.title); setInterpretation(theme.interpretation); setArticleIds(theme.articleIds); }}>Editar</Button><Button type="button" size="icon" variant="ghost" className="h-8 w-8 text-slate-400 hover:bg-red-50 hover:text-red-600" onClick={() => remove.mutate({ projectId, themeId: theme.id })} aria-label={`Remover tema ${theme.title}`}><Trash2 className="h-4 w-4" /></Button></div></div><div className="mt-4 border-l-2 border-amber-300 bg-amber-50/60 p-3"><p className="text-[10px] font-bold tracking-[.14em] text-amber-900">EVIDÊNCIAS SELECIONADAS</p><ul className="mt-2 space-y-1.5 text-xs leading-5 text-slate-700">{evidenceArticles.map(article => <li key={article.id}>• {article.title}</li>)}</ul></div></article>; })}</div><div className="border border-slate-200 bg-slate-50 p-5"><p className="text-xs font-bold tracking-[.15em] text-slate-700">{editingId ? "EDITAR TEMA" : "NOVO TEMA"}</p><div className="mt-4 space-y-4"><div className="space-y-2"><Label htmlFor="narrative-title">Nome do tema</Label><Input id="narrative-title" value={title} onChange={event => setTitle(event.target.value)} placeholder="Ex.: barreiras de implementação" className="bg-white" /></div><div className="space-y-2"><Label htmlFor="narrative-interpretation">Interpretação do pesquisador</Label><Textarea id="narrative-interpretation" value={interpretation} onChange={event => setInterpretation(event.target.value)} placeholder="Descreva o padrão, a tensão ou a hipótese interpretativa, distinguindo-o dos dados brutos." className="min-h-32 bg-white" /></div><div className="space-y-2"><Label>Estudos que sustentam o tema</Label><ScrollArea className="h-40 border border-slate-200 bg-white"><div className="space-y-1 p-2">{articles.map(article => <button key={article.id} type="button" onClick={() => toggleArticle(article.id)} className={cn("w-full border px-3 py-2 text-left text-xs leading-5", articleIds.includes(article.id) ? "border-amber-400 bg-amber-50 text-[#0A192F]" : "border-transparent hover:border-slate-200 hover:bg-slate-50")}><span className="mr-2 font-bold text-amber-800">{articleIds.includes(article.id) ? "✓" : "○"}</span>{article.title}</button>)}</div></ScrollArea></div><div className="flex gap-2"><Button type="button" onClick={save} disabled={create.isPending || update.isPending} className="flex-1 rounded-none bg-[#0A192F] hover:bg-[#152c4b]">{create.isPending || update.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <><NotebookPen className="mr-2 h-4 w-4" />{editingId ? "Atualizar tema" : "Salvar tema"}</>}</Button>{editingId && <Button type="button" variant="outline" className="rounded-none" onClick={reset}>Cancelar</Button>}</div></div></div></div></section>;
}

function SynthesisView({ projectId, synthesis, articleCount, projectName }: { projectId: number; synthesis: any; articleCount: number; projectName: string }) {
  const utils = trpc.useUtils(); const [selectedCitation, setSelectedCitation] = useState<any>(null);
  const generate = trpc.cartographer.generateSynthesis.useMutation({ onSuccess: () => { utils.cartographer.projectOverview.invalidate({ projectId }); toast.success("Síntese pronta. Clique nas referências para reabrir a evidência."); }, onError: error => toast.error(error.message) });
  const citations = parseCitationList(synthesis?.citations);
  const paragraphNodes = (synthesis?.content ?? "").split(/(\[\d+\])/g).map((part: string, index: number) => { const match = part.match(/^\[(\d+)\]$/); if (!match) return part; const citation = citations.find((item: any) => item.referenceNumber === Number(match[1])); return citation ? <button key={index} className="mx-0.5 inline-flex h-5 min-w-5 items-center justify-center border border-amber-300 bg-amber-100 px-1 text-[10px] font-bold text-amber-950 hover:bg-amber-300" onClick={() => setSelectedCitation(citation)}>{match[1]}</button> : null; });
  if (!articleCount) return <div className="border border-dashed border-slate-300 bg-white p-12 text-center"><Sparkles className="mx-auto h-7 w-7 text-amber-700" /><h3 className="mt-4 font-reading text-xl font-bold text-[#0A192F]">Ainda não há evidência selecionada.</h3><p className="mt-2 text-sm text-slate-500">Salve artigos com resumos públicos para construir uma síntese auditável.</p></div>;
  const exportInput = { projectName, content: synthesis?.content ?? "", citations };
  return <section className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_300px]"><article className="border border-slate-200 bg-white"><div className="flex flex-col gap-4 border-b border-slate-200 bg-slate-50 px-6 py-5 md:flex-row md:items-center md:justify-between"><div><p className="text-[10px] font-bold tracking-[.18em] text-amber-700">MESA DE SÍNTESE</p><h3 className="mt-1 font-reading text-xl font-black text-[#0A192F]">Argumento com trilha de prova.</h3></div>{synthesis?.status === "ready" && <div className="inline-flex items-center gap-2 border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><CircleCheck className="h-4 w-4" />Evidências verificadas</div>}</div>{synthesis?.status === "ready" ? <div className="p-7 md:p-10"><div className="mb-7 flex flex-col justify-between gap-4 border-b border-slate-100 pb-5 md:flex-row md:items-start"><div className="flex items-center gap-2"><span className="h-2 w-2 bg-emerald-500" /><span className="text-xs font-bold uppercase tracking-[.14em] text-emerald-800">Cadeia de evidência verificada</span></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" className="rounded-none border-slate-300" onClick={() => downloadSynthesisDocx(exportInput).catch(() => toast.error("Não foi possível gerar o DOCX."))}><FileDown className="mr-1.5 h-3.5 w-3.5" />Exportar DOCX</Button><Button size="sm" variant="outline" className="rounded-none border-slate-300" onClick={() => downloadSynthesisLatex(exportInput)}><FileCode2 className="mr-1.5 h-3.5 w-3.5" />Exportar LaTeX</Button></div></div><p className="font-reading text-lg leading-9 text-[#0A192F]">{paragraphNodes}</p><div className="mt-8 border-t border-slate-200 pt-5 text-xs text-slate-500"><strong className="text-[#0A192F]">Como auditar:</strong> clique em qualquer referência dourada para revelar o trecho literal do resumo que a sustenta. As exportações incluem a afirmação, a referência e o trecho de origem.</div></div> : <div className="p-7 md:p-10"><p className="text-xs font-bold tracking-[.15em] text-amber-700">PRÓXIMO PASSO</p><h3 className="mt-3 font-reading text-2xl font-black text-[#0A192F]">Conecte os estudos, sem apagar suas fontes.</h3><p className="mt-4 max-w-2xl leading-7 text-slate-600">A síntese usa apenas os resumos dos artigos salvos. Cada afirmação factual recebe uma referência clicável — e só é exibida se o trecho citado puder ser encontrado no original.</p><Button className="mt-7 rounded-none bg-[#0A192F] hover:bg-[#152c4b]" onClick={() => generate.mutate({ projectId })} disabled={generate.isPending}>{generate.isPending || synthesis?.status === "generating" ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Construindo síntese…</> : <><Sparkles className="mr-2 h-4 w-4" />Gerar síntese auditável</>}</Button>{synthesis?.status === "error" && <p className="mt-4 text-sm text-red-700"><CircleAlert className="mr-1 inline h-4 w-4" />{synthesis.errorMessage}</p>}</div>}</article><aside className="h-fit border border-slate-200 bg-[#0A192F] p-6 text-white xl:sticky xl:top-24"><p className="text-[10px] font-bold tracking-[.18em] text-amber-300">REFERÊNCIAS ATIVAS</p><p className="mt-3 text-sm leading-6 text-slate-300">Cada marcador reabre a origem literal que sustenta a afirmação.</p><div className="mt-6 space-y-3">{citations.length ? citations.map((citation: any) => <button key={`${citation.referenceNumber}-${citation.articleId}`} onClick={() => setSelectedCitation(citation)} className="w-full border-l-2 border-amber-300 bg-white/5 p-3 text-left text-xs leading-5 text-slate-200 hover:bg-white/10"><span className="font-bold text-amber-300">[{citation.referenceNumber}]</span> {citation.articleTitle}</button>) : <p className="border-l-2 border-white/25 pl-3 text-sm leading-6 text-slate-300">As referências auditáveis aparecerão aqui após a geração.</p>}</div></aside><Dialog open={Boolean(selectedCitation)} onOpenChange={open => !open && setSelectedCitation(null)}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle className="font-reading text-xl text-[#0A192F]">Evidência da referência [{selectedCitation?.referenceNumber}]</DialogTitle><DialogDescription>{selectedCitation?.articleTitle}</DialogDescription></DialogHeader><div className="border-l-2 border-amber-400 bg-amber-50 p-5"><Quote className="mb-2 h-4 w-4 text-amber-800" /><p className="font-reading text-base leading-7 text-[#0A192F]">“{selectedCitation?.sourceText}”</p></div><p className="text-sm text-slate-600"><strong>Afirmação na síntese:</strong> {selectedCitation?.claim}</p></DialogContent></Dialog></section>;
}

export default function Home() {
  const [location] = useLocation(); const page = pageTitles[location] ?? pageTitles["/"];
  const reticulaContext = useMemo(() => readReticulaSearchContext(), []);
  const [cartographerHash, setCartographerHash] = useState(() => typeof window === "undefined" ? "" : window.location.hash);
  const { isAuthenticated } = useAuth();
  const { data: projects = [], isLoading: projectsLoading } = trpc.cartographer.projects.useQuery(undefined, { enabled: isAuthenticated });
  const [projectId, setProjectId] = useState<number | null>(null);
  useEffect(() => {
    if (typeof window === "undefined") return;
    const updateHash = () => setCartographerHash(window.location.hash);
    window.addEventListener("hashchange", updateHash);
    return () => window.removeEventListener("hashchange", updateHash);
  }, []);
  useEffect(() => { if (!projectId && projects[0]) setProjectId(projects[0].id); }, [projects, projectId]);
  const overviewInput = useMemo(() => ({ projectId: projectId ?? 0 }), [projectId]);
  const overview = trpc.cartographer.projectOverview.useQuery(overviewInput, { enabled: Boolean(projectId) && isAuthenticated });
  // O DashboardLayout controla a capa e o carregamento de autenticação. Esta
  // saída evita executar áreas protegidas com estado de sessão ainda ausente.
  if (!isAuthenticated) return <DashboardLayout>{null}</DashboardLayout>;
  if (projectsLoading) return <DashboardLayout><div className="flex min-h-screen items-center justify-center"><Loader2 className="h-6 w-6 animate-spin text-amber-700" /></div></DashboardLayout>;
  if (!projectId) return <DashboardLayout><EmptyProject onCreated={setProjectId} /></DashboardLayout>;
  const data = overview.data; const articles = data?.articles ?? []; const savedIds = new Set(articles.map((article: any) => article.externalId));
  if (location === "/") return <DashboardLayout><AcademiaDashboard projectId={projectId} data={data} articles={articles} /></DashboardLayout>;
  const cartographerPanel = cartographerHash === "#cartographer-integridade" || cartographerHash === "#cartographer-citacoes" ? <CartographerEvidenceTools projectId={projectId} articles={articles} /> : null;
  const inner = <><ProjectHeader projectId={projectId} onProjectChange={setProjectId} /><div className="mx-auto max-w-[1440px] px-6 py-8 md:px-10"><div className="mb-8 max-w-3xl"><p className="text-[10px] font-bold tracking-[.18em] text-amber-700">{page.eyebrow}</p><h1 className="mt-2 font-reading text-3xl font-black tracking-tight text-[#0A192F] md:text-4xl">{page.title}</h1><p className="mt-3 max-w-2xl leading-7 text-slate-600">{page.description}</p></div>{overview.isLoading ? <div className="flex h-64 items-center justify-center"><Loader2 className="h-6 w-6 animate-spin text-amber-700" /></div> : cartographerPanel ?? (location === "/search" || location === "/discover" ? <DiscoveryWorkspace projectId={projectId} savedExternalIds={savedIds} savedCount={articles.length} context={reticulaContext} /> : location === "/library" ? <LibraryView projectId={projectId} projectName={data?.project?.name ?? "Projeto AcademiaOS"} articles={articles} screenings={data?.screenings} possibleDuplicateGroups={data?.possibleDuplicateGroups} possibleOverlapPairs={data?.possibleOverlapPairs} prisma={data?.prisma} /> : location === "/synthesis" ? <><SynthesisView projectId={projectId} synthesis={data?.synthesis} articleCount={articles.length} projectName={data?.project?.name ?? "Projeto AcademiaOS"} /><NarrativeThemes projectId={projectId} articles={articles} themes={data?.narrativeThemes} /></> : <DashboardView projectId={projectId} data={data} articles={articles} />)}</div></>;
  return <DashboardLayout>{inner}</DashboardLayout>;
}

function DashboardView({ projectId, data, articles }: { projectId: number; data: any; articles: any[] }) {
  const [, setLocation] = useLocation(); const unread = articles.filter(article => !article.isRead).slice(0, 4); const progress = data?.metrics?.saved ? Math.round((data.metrics.extracted / data.metrics.saved) * 100) : 0;
  return <div className="space-y-8"><Metrics metrics={data?.metrics ?? { saved: 0, read: 0, extracted: 0 }} synthesisStatus={data?.synthesis?.status} /><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><section className="border border-slate-200 bg-white"><div className="flex items-center justify-between border-b border-slate-200 px-6 py-5"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-800">Próxima ação</p><h2 className="mt-1 font-reading text-xl font-bold text-[#0A192F]">Conduza a seleção com intenção.</h2></div><Button onClick={() => setLocation("/search")} className="rounded-none bg-[#0A192F] hover:bg-[#152c4b]"><Search className="mr-2 h-4 w-4" />Buscar</Button></div>{unread.length ? <div>{unread.map(article => <div key={article.id} className="flex items-center gap-3 border-b border-slate-100 px-6 py-4 last:border-b-0"><Initials name={article.authors[0] || article.title} /><div className="min-w-0 flex-1"><p className="truncate font-reading text-sm font-bold text-[#0A192F]">{article.title}</p><p className="mt-1 text-xs text-slate-500">{article.authors[0] || "Autoria não informada"} · {article.publicationYear ?? "s/d"}</p></div><Button variant="ghost" size="sm" onClick={() => setLocation("/library")} className="text-amber-800">Abrir<ArrowRight className="ml-1 h-3 w-3" /></Button></div>)}</div> : <div className="p-8 text-center text-sm text-slate-500">Quando você salvar estudos, os próximos itens de leitura aparecerão aqui.</div>}</section><section className="border border-slate-200 bg-[#0A192F] p-6 text-white"><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-300">Cobertura da extração</p><p className="mt-4 font-reading text-4xl font-black">{progress}%</p><Progress value={progress} className="mt-5 h-1.5 bg-white/20 [&>div]:bg-amber-400" /><p className="mt-5 text-sm leading-6 text-slate-300">{data?.metrics?.extracted ?? 0} de {data?.metrics?.saved ?? 0} artigos possuem campos estruturados e rastreáveis.</p><Button variant="outline" onClick={() => setLocation("/library")} className="mt-6 rounded-none border-amber-300 bg-transparent text-amber-200 hover:bg-amber-300 hover:text-slate-950">Gerenciar extrações</Button></section></div><section className="border border-amber-200 bg-amber-50 p-6"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-center"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-800">Síntese auditável</p><h2 className="mt-1 font-reading text-xl font-bold text-[#0A192F]">{data?.synthesis?.status === "ready" ? "Sua síntese está pronta para inspeção." : "As evidências ainda não foram conectadas."}</h2><p className="mt-2 text-sm text-slate-600">O modelo não acrescenta fontes externas e toda citação aponta para um trecho verificável.</p></div><Button onClick={() => setLocation("/synthesis")} className="rounded-none bg-amber-400 text-slate-950 hover:bg-amber-300">{data?.synthesis?.status === "ready" ? "Abrir síntese" : "Preparar síntese"}<ArrowRight className="ml-2 h-4 w-4" /></Button></div></section></div>;
}

function AcademiaDashboard({ projectId, data, articles }: { projectId: number; data: any; articles: any[] }) {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const { data: lapisProjects = [] } = trpc.lapis.projects.useQuery(undefined, { enabled: Boolean(user) });
  const activeLapisProject = lapisProjects.find((item: any) => item.reviewProjectId === projectId);
  const activeLapisProjectId = activeLapisProject?.id ?? 0;
  const workspaceInput = useMemo(() => ({ lapisProjectId: activeLapisProjectId }), [activeLapisProjectId]);
  const activeModuleQuery = { enabled: Boolean(activeLapisProjectId) };
  const { data: lapisWorkspace } = trpc.lapis.workspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: vaultWorkspace } = trpc.lapis.vaultWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: qualiaWorkspace } = trpc.lapis.qualiaWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: analystWorkspace } = trpc.lapis.analystWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: scriptoriumWorkspace } = trpc.lapis.scriptoriumWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: matchmakerWorkspace } = trpc.lapis.matchmakerWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const { data: vigilWorkspace } = trpc.lapis.vigilWorkspace.useQuery(workspaceInput, activeModuleQuery);
  const project = data?.project;
  const metrics = data?.metrics ?? { saved: 0, read: 0, extracted: 0 };
  const unreadCount = articles.filter((article: any) => !article.isRead).length;
  const cycle = deriveResearchCycle({
    hasIdea: Boolean(activeLapisProject),
    hasLiterature: metrics.saved > 0,
    hasProtocol: Boolean(lapisWorkspace?.method),
    hasPreregistration: Boolean(lapisWorkspace?.preregistration),
    hasData: (vaultWorkspace?.datasets?.length ?? 0) > 0,
    hasAnalysis: Boolean(analystWorkspace?.plan || (qualiaWorkspace?.corpora?.length ?? 0) > 0),
    hasWriting: Boolean(scriptoriumWorkspace?.document || lapisWorkspace?.manuscript),
    hasSubmission: Boolean(matchmakerWorkspace?.submission),
    hasPublication: Boolean(vigilWorkspace?.assessment),
  });
  const cycleIcons = [Lightbulb, BookOpenText, NotebookPen, ClipboardCheck, Database, BarChart3, FileText, Send, ShieldCheck];
  const nextActions = cycle.steps.filter(step => step.state !== "done").slice(0, 2);
  const firstName = user?.name?.trim().split(/\s+/)[0] || "Pesquisador";

  return <div className="mx-auto max-w-[1480px] px-5 py-7 md:px-10 md:py-9">
    <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.18em] text-amber-700">Visão geral</p><h1 className="mt-1 font-reading text-3xl font-black tracking-tight text-[#0A192F] md:text-[38px]">Bom dia, {firstName}</h1><p className="mt-2 text-sm text-slate-600">Acompanhe o projeto ativo e avance pelo ciclo de pesquisa com artefatos rastreáveis.</p></div>

    <section className="rounded-xl border border-slate-200 bg-white px-5 py-6 shadow-sm md:px-7"><div className="flex flex-col justify-between gap-3 md:flex-row md:items-center"><div><h2 className="font-reading text-xl font-bold text-[#0A192F]">Timeline do ciclo de vida</h2><p className="mt-1 text-xs text-slate-500">{cycle.completedCount} de {cycle.steps.length} etapas possuem artefatos registrados neste projeto.</p></div><Button variant="outline" size="sm" onClick={() => setLocation(cycle.currentStep.path)} className="w-fit border-amber-300 text-amber-900 hover:bg-amber-50">Continuar em {cycle.currentStep.module}<ArrowRight className="ml-2 h-3.5 w-3.5" /></Button></div><div className="mt-7 overflow-x-auto pb-2"><div className="relative flex min-w-[900px] items-start justify-between"><div className="absolute left-7 right-7 top-6 h-px bg-slate-200" />{cycle.steps.map((step, index) => { const Icon = cycleIcons[index]; const tone = step.state === "done" ? "border-emerald-400 bg-emerald-50 text-emerald-600" : step.state === "current" ? "border-amber-400 bg-amber-50 text-amber-700 ring-4 ring-amber-100" : "border-slate-200 bg-white text-slate-400"; return <button type="button" key={step.id} onClick={() => setLocation(step.path)} className="relative z-10 flex w-[100px] shrink-0 flex-col items-center text-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400"><span className={cn("flex h-12 w-12 items-center justify-center rounded-full border-2", tone)}>{step.state === "done" ? <Check className="h-5 w-5" /> : <Icon className="h-5 w-5" />}</span><span className="mt-3 text-xs font-bold text-[#0A192F]">{step.label}</span><span className={cn("mt-1 text-[10px] leading-3", step.state === "current" ? "font-bold text-amber-800" : "text-slate-500")}>{step.module}</span></button>; })}</div></div></section>

    <section className="mt-6 grid gap-5 xl:grid-cols-3">
      <article className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-start justify-between gap-4"><div className="min-w-0"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-amber-700">Projeto ativo</p><h2 className="mt-2 font-reading text-xl font-black leading-snug text-[#0A192F]">{project?.name ?? "Projeto de pesquisa"}</h2></div><FolderPlus className="h-5 w-5 shrink-0 text-slate-400" /></div><p className="mt-4 line-clamp-3 text-sm leading-6 text-slate-600">{project?.researchQuestion || "Defina uma pergunta de pesquisa para orientar os próximos artefatos do ciclo."}</p><div className="mt-6 border-t border-slate-100 pt-4"><div className="flex items-center justify-between text-xs"><span className="text-slate-500">Progresso do ciclo</span><span className="font-bold text-[#0A192F]">{cycle.progressPercent}%</span></div><Progress value={cycle.progressPercent} className="mt-2 h-2 bg-slate-100 [&>div]:bg-amber-400" /><button onClick={() => setLocation("/projects")} className="mt-5 inline-flex items-center text-sm font-bold text-[#2563b8] hover:text-[#0A2348]">Acessar projeto <ArrowRight className="ml-2 h-4 w-4" /></button></div></article>

      <article className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-blue-50 text-[#2563b8]"><ClipboardCheck className="h-5 w-5" /></span><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-slate-400">Tarefas do ciclo</p><h2 className="font-reading text-lg font-bold text-[#0A192F]">Próximos movimentos</h2></div></div><span className="text-xs font-bold text-slate-400">{nextActions.length}</span></div><div className="mt-5 space-y-3">{nextActions.length ? nextActions.map(step => <button type="button" key={step.id} onClick={() => setLocation(step.path)} className="flex w-full items-center justify-between gap-3 rounded-lg border border-slate-100 bg-slate-50 px-3 py-3 text-left hover:border-amber-200 hover:bg-amber-50"><span className="flex min-w-0 items-center gap-3"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full border border-amber-400 text-amber-700"><ArrowRight className="h-3 w-3" /></span><span><span className="block text-sm font-semibold text-[#0A192F]">Concluir {step.label.toLocaleLowerCase("pt-BR")}</span><span className="block text-[11px] text-slate-500">{step.module}</span></span></span><ArrowRight className="h-4 w-4 shrink-0 text-slate-400" /></button>) : <p className="rounded-lg bg-emerald-50 p-4 text-sm leading-6 text-emerald-800">Os nove marcos do ciclo têm artefatos registrados. Continue o monitoramento no Vigil.</p>}</div></article>

      <article className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-violet-50 text-violet-700"><Sparkles className="h-5 w-5" /></span><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-slate-400">Assistente de IA</p><h2 className="font-reading text-lg font-bold text-[#0A192F]">Apoio com rastreabilidade</h2></div></div><div className="mt-5 rounded-lg bg-violet-50 p-4"><p className="text-sm leading-6 text-violet-950">O próximo artefato é <strong>{cycle.currentStep.label.toLocaleLowerCase("pt-BR")}</strong>. Abra o {cycle.currentStep.module} para trabalhar com evidências, métodos e decisões preservadas.</p></div><Button onClick={() => setLocation(cycle.currentStep.path)} variant="ghost" className="mt-4 px-0 text-[#2563b8] hover:bg-transparent hover:text-[#0A2348]">Ir para {cycle.currentStep.module}<ArrowRight className="ml-2 h-4 w-4" /></Button></article>
    </section>

    <section className="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4"><DashboardMetric icon={BookOpenCheck} label="Estudos salvos" value={metrics.saved} detail="na biblioteca do projeto" tone="blue" /><DashboardMetric icon={Library} label="Papers em leitura" value={unreadCount} detail="com leitura pendente" tone="green" /><DashboardMetric icon={FileText} label="Extrações verificadas" value={metrics.extracted} detail="com campos rastreáveis" tone="amber" /><DashboardMetric icon={BarChart3} label="Avanço do ciclo" value={`${cycle.progressPercent}%`} detail="marcos com artefato persistido" tone="violet" /></section>
  </div>;
}

function DashboardMetric({ icon: Icon, label, value, detail, tone }: { icon: React.ComponentType<{ className?: string }>; label: string; value: string | number; detail: string; tone: "blue" | "green" | "amber" | "violet" }) {
  const tones = { blue: "bg-blue-50 text-[#2563b8]", green: "bg-emerald-50 text-emerald-600", amber: "bg-amber-50 text-amber-700", violet: "bg-violet-50 text-violet-700" };
  return <article className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start gap-3"><span className={cn("flex h-10 w-10 items-center justify-center rounded-lg", tones[tone])}><Icon className="h-5 w-5" /></span><div><p className="text-xs font-semibold text-slate-600">{label}</p><p className="mt-1 font-reading text-3xl font-black text-[#0A192F]">{value}</p><p className="mt-1 text-[11px] text-slate-500">{detail}</p></div></div></article>;
}

function MetricTile({ label, value, detail }: { label: string; value: string | number; detail: string }) { return <div className="border border-slate-200 bg-slate-50 p-4"><p className="font-reading text-2xl font-black text-[#0A192F]">{value}</p><p className="mt-1 text-xs font-bold text-slate-700">{label}</p><p className="mt-1 text-[11px] text-slate-500">{detail}</p></div>; }
